import { useRef, useEffect, useState } from 'react';

// ── Static bbox definitions (randomized positions each tick) ──
const BASE_BOXES = [
  { baseTop: 32, baseLeft: 8,  w: 20, h: 30, type: 'green',  label: 'Vehicle Detected',  alwaysShow: true  },
  { baseTop: 38, baseLeft: 52, w: 22, h: 32, type: 'red',    label: 'No Plate Detected', alwaysShow: false },
  { baseTop: 44, baseLeft: 30, w: 16, h: 26, type: 'orange', label: 'Plate Obscured',    alwaysShow: false },
  { baseTop: 50, baseLeft: 70, w: 14, h: 22, type: 'green',  label: 'Vehicle OK',        alwaysShow: true  },
];

const CAMERAS = [
  'CAM-01 · Gate A',
  'CAM-02 · Gate B',
  'CAM-03 · Parkir',
  'CAM-04 · Exit',
];

function BBox({ box }) {
  const colorMap = {
    green:  { border: 'var(--green)',  tag: 'bbox-tag-green'  },
    orange: { border: 'var(--orange)', tag: 'bbox-tag-orange' },
    red:    { border: 'var(--red)',    tag: 'bbox-tag-red'    },
  };
  const c = colorMap[box.type] || colorMap.green;

  return (
    <div
      className={`bbox bbox-${box.type}`}
      style={{
        top:    `${box.top}%`,
        left:   `${box.left}%`,
        width:  `${box.w}%`,
        height: `${box.h}%`,
        border: `1.5px solid ${c.border}`,
      }}
    >
      <span className={`bbox-tag ${c.tag}`}>{box.label}</span>
    </div>
  );
}

export default function LiveMonitor({ isRunning, stream }) {
  const videoRef       = useRef(null);
  const [boxes, setBoxes]   = useState([]);
  const [frame, setFrame]   = useState(0);
  const [activeCam, setActiveCam] = useState(0);

  // Attach stream to video element
  useEffect(() => {
    if (videoRef.current && stream) {
      videoRef.current.srcObject = stream;
    }
  }, [stream]);

  // Animate bboxes while running
  useEffect(() => {
    if (!isRunning) { setBoxes([]); setFrame(0); return; }

    const id = setInterval(() => {
      setFrame(f => f + 1);
      setBoxes(
        BASE_BOXES
          .filter(b => b.alwaysShow || Math.random() > 0.3)
          .map(b => ({
            ...b,
            top:  b.baseTop  + (Math.random() - 0.5) * 2,
            left: b.baseLeft + (Math.random() - 0.5) * 1.5,
          }))
      );
    }, 1800);

    return () => clearInterval(id);
  }, [isRunning]);

  return (
    <div className="card">
      <div className="card-header">
        <span className="card-title">
          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <circle cx="12" cy="12" r="3"/>
            <path d="M20.188 10.934c.2.646.312 1.358.312 2.066 0 4.418-3.582 8-8 8s-8-3.582-8-8 3.582-8 8-8c.708 0 1.42.112 2.066.312"/>
            <path d="M22 2L14 10"/>
          </svg>
          Live Detection Feed
        </span>

        <div style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
          {isRunning && (
            <span style={{
              fontFamily: 'var(--font-mono)', fontSize: 8.5,
              color: 'var(--text-3)', letterSpacing: '1px',
            }}>
              FRAME #{String(frame).padStart(5, '0')}
            </span>
          )}
          <span className={`status-pill ${isRunning ? 'pill-green' : 'pill-accent'}`}>
            <span className={`dot ${isRunning ? 'dot-green dot-pulse' : 'dot-gray'}`}/>
            {isRunning ? 'AI ACTIVE' : 'STANDBY'}
          </span>
        </div>
      </div>

      <div className="card-body" style={{ padding: 14 }}>
        {/* ── Main video shell ── */}
        <div className="video-shell">

          {/* Video element */}
          <video
            ref={videoRef}
            autoPlay
            muted
            playsInline
            style={{
              display: (isRunning && stream) ? 'block' : 'none',
              width: '100%', height: '100%', objectFit: 'cover',
            }}
          />

          {/* Placeholder */}
          {(!isRunning || !stream) && (
            <div className="grid-bg">
              <div style={{ fontSize: 44, opacity: 0.18 }}>📷</div>
              <div style={{
                fontFamily: 'var(--font-display)',
                fontSize: 9,
                color: 'var(--text-4)',
                letterSpacing: '3px',
                textTransform: 'uppercase',
              }}>
                No Feed Active
              </div>
              <div style={{
                fontFamily: 'var(--font-mono)',
                fontSize: 8.5,
                color: 'var(--text-4)',
                letterSpacing: '1.5px',
                opacity: 0.6,
                marginTop: 4,
              }}>
                Tekan START SCREEN DETECTION untuk memulai
              </div>
            </div>
          )}

          {/* HUD overlay — rendered when running */}
          {isRunning && (
            <div className="hud-overlay">
              {/* Corner brackets */}
              <div className="hud-corner tl"/>
              <div className="hud-corner tr"/>
              <div className="hud-corner bl"/>
              <div className="hud-corner br"/>

              {/* Vertical scan line */}
              <div className="scan-line-v"/>

              {/* Bounding boxes */}
              {boxes.map((b, i) => <BBox key={i} box={b}/>)}

              {/* Bottom-left HUD info */}
              <div className="hud-info">
                <div>MODEL: YOLOv8-CVD · v2.4</div>
                <div>CONFIDENCE: 94.7%  ·  FPS: 24</div>
                <div>RESOLUTION: 1080p  ·  LATENCY: 12ms</div>
              </div>

              {/* REC badge */}
              <div className="rec-badge">
                <span className="rec-dot"/>
                REC
              </div>
            </div>
          )}
        </div>

        {/* ── Camera thumbnail strip ── */}
        <div style={{ marginTop: 12 }}>
          <div style={{
            fontFamily: 'var(--font-display)',
            fontSize: 8,
            color: 'var(--text-3)',
            letterSpacing: '2.5px',
            textTransform: 'uppercase',
            marginBottom: 8,
          }}>
            Other Camera Feeds
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 8 }}>
            {CAMERAS.map((cam, i) => (
              <div
                key={i}
                onClick={() => setActiveCam(i)}
                style={{
                  aspectRatio: '16/9',
                  borderRadius: 6,
                  border: `1px solid ${activeCam === i ? 'var(--accent)' : 'var(--border)'}`,
                  boxShadow: activeCam === i ? 'var(--shadow-glow)' : 'none',
                  background: '#000',
                  overflow: 'hidden',
                  cursor: 'pointer',
                  transition: 'border-color 0.2s, box-shadow 0.2s',
                  position: 'relative',
                }}
              >
                {/* Mini grid texture */}
                <div style={{
                  width: '100%', height: '100%',
                  backgroundImage:
                    'linear-gradient(rgba(0,194,255,0.03) 1px, transparent 1px),' +
                    'linear-gradient(90deg, rgba(0,194,255,0.03) 1px, transparent 1px)',
                  backgroundSize: '16px 16px',
                  display: 'flex',
                  alignItems: 'flex-end',
                }}>
                  <div style={{
                    width: '100%',
                    padding: '3px 5px',
                    background: 'rgba(0,0,0,0.65)',
                    fontFamily: 'var(--font-mono)',
                    fontSize: 7.5,
                    color: activeCam === i ? 'var(--accent)' : 'var(--text-3)',
                    letterSpacing: '0.8px',
                  }}>
                    {cam}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
